ALTER TYPE tool_call_status ADD VALUE IF NOT EXISTS 'bad_arguments' AFTER 'failed';

CREATE TABLE tool_failure_counts (
  tool text NOT NULL,
  day date NOT NULL,
  failures integer NOT NULL DEFAULT 0,
  PRIMARY KEY (tool, day)
);

CREATE OR REPLACE FUNCTION count_tool_failure() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status IN ('failed', 'bad_arguments') THEN
    INSERT INTO tool_failure_counts (tool, day, failures)
    VALUES (NEW.tool, current_date, 1)
    ON CONFLICT (tool, day) DO UPDATE SET failures = tool_failure_counts.failures + 1;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER tool_calls_count_failure
  AFTER INSERT OR UPDATE OF status ON tool_calls
  FOR EACH ROW EXECUTE FUNCTION count_tool_failure();

DROP TABLE IF EXISTS tool_error_log;
